import argparse
import csv
import json
from decimal import Decimal, InvalidOperation

CUSTOMERS_FILE = "/inputs/customers.csv"
ORDERS_FILE = "/inputs/orders.csv"


def find_col(header, candidates):
    lowered = [h.strip().lower() for h in header]
    for cand in candidates:
        if cand in lowered:
            return lowered.index(cand)
    for i, h in enumerate(lowered):
        for cand in candidates:
            if cand in h:
                return i
    raise KeyError(candidates)


def parse_amount(value):
    s = str(value).strip().replace(",", "").replace("$", "")
    return Decimal(s)


def load_west_ids():
    try:
        with open(CUSTOMERS_FILE, newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            try:
                header = next(reader)
            except StopIteration:
                return set()
            id_idx = find_col(header, ["customer_id"])
            region_idx = find_col(header, ["region"])
            west_ids = set()
            for row in reader:
                if len(row) <= max(id_idx, region_idx):
                    continue
                if row[region_idx].strip().lower() == "west":
                    west_ids.add(row[id_idx].strip())
            return west_ids
    except (FileNotFoundError, KeyError):
        return set()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    json.loads(args.payload)

    west_ids = load_west_ids()
    total = Decimal("0")

    try:
        with open(ORDERS_FILE, newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            try:
                header = next(reader)
            except StopIteration:
                header = None
            if header is not None:
                cid_idx = find_col(header, ["customer_id"])
                amount_idx = find_col(
                    header, ["amount", "order_amount", "total_amount"]
                )
                for row in reader:
                    if len(row) <= max(cid_idx, amount_idx):
                        continue
                    if row[cid_idx].strip() in west_ids:
                        try:
                            total += parse_amount(row[amount_idx])
                        except (InvalidOperation, ValueError):
                            continue
    except FileNotFoundError:
        pass

    out = total.normalize()
    print(format(out, "f"))


if __name__ == "__main__":
    main()

import argparse, json, csv

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    cfg = json.loads(args.payload)
    path = cfg.get("path", "/inputs/ledger.csv")
    total = 0.0
    with open(path, newline="") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            header = []
        amount_idx = None
        for i, h in enumerate(header):
            if h.strip().lower() == "amount":
                amount_idx = i
                break
        for row in reader:
            if not row or all(cell.strip() == "" for cell in row):
                continue
            if amount_idx is None or amount_idx >= len(row):
                continue
            raw = row[amount_idx].strip()
            if raw == "":
                continue
            cleaned = raw.replace("$", "").replace(",", "")
            try:
                total += float(cleaned)
            except ValueError:
                continue
    print(f"{total:.2f}")

if __name__ == "__main__":
    main()

import argparse
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    config = json.loads(args.payload) if args.payload else {}
    path = config.get("path", "/inputs/server.log")
    start = 8 * 3600
    end = 8 * 3600 + 30 * 60
    count = 0
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split(None, 2)
            if len(parts) < 2:
                continue
            time_part, level = parts[0], parts[1]
            if level != "ERROR":
                continue
            try:
                hh, mm, ss = time_part.split(":")
                seconds = int(hh) * 3600 + int(mm) * 60 + int(ss)
            except Exception:
                continue
            if start <= seconds < end:
                count += 1
    print(count, end="")

if __name__ == "__main__":
    main()

import argparse
import csv
import json
from decimal import Decimal

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()

    try:
        kwargs = json.loads(args.payload) if args.payload else {}
    except Exception:
        kwargs = {}

    customers_path = kwargs.get("customers", "/inputs/customers.csv")
    orders_path = kwargs.get("orders", "/inputs/orders.csv")

    west_ids = set()
    with open(customers_path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if row.get("region") == "west":
                west_ids.add(row.get("customer_id"))

    total = Decimal("0")
    with open(orders_path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if row.get("customer_id") in west_ids:
                try:
                    total += Decimal(row.get("amount", "0"))
                except Exception:
                    continue

    print(total)

if __name__ == "__main__":
    main()

import argparse
import json
import csv

def parse_amount(text):
    s = text.strip()
    s = s.replace('$', '').replace(',', '')
    negative = False
    if s.startswith('(') and s.endswith(')'):
        s = s[1:-1]
        negative = True
    if s.startswith('-'):
        s = s[1:]
        negative = True
    s = s.replace('$', '').replace(',', '')
    value = float(s)
    return -value if negative else value

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('payload')
    args = parser.parse_args()
    try:
        json.loads(args.payload)
    except Exception:
        pass
    total = 0.0
    with open('/inputs/ledger.csv', newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        amount_idx = None
        if header:
            for i, h in enumerate(header):
                if 'amount' in h.strip().lower():
                    amount_idx = i
                    break
        if amount_idx is not None:
            for row in reader:
                if not row or all(cell.strip() == '' for cell in row):
                    continue
                if amount_idx < len(row):
                    raw = row[amount_idx]
                    if raw is not None and raw.strip() != '':
                        try:
                            value = parse_amount(raw)
                            total += value
                            print(f'{raw}\t{value:.2f}')
                        except Exception:
                            pass
    print(f'{total:.2f}')

if __name__ == '__main__':
    main()

import argparse, csv, json

def _get(row, candidates):
    for c in candidates:
        if c in row:
            return row[c]
    return None

def main(customers_path, orders_path):
    regions = {}
    with open(customers_path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            cid = _get(row, ['customer_id', 'customer id', 'customerid', 'cust_id', 'cust id'])
            region = _get(row, ['region'])
            if cid is not None:
                regions[cid] = region

    total = 0.0
    with open(orders_path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            cid = _get(row, ['customer_id', 'customer id', 'customerid', 'cust_id', 'cust id'])
            amount = _get(row, ['amount', 'order_amount', 'order amount', 'total', 'value'])
            if regions.get(cid) == 'west' and amount is not None:
                try:
                    total += float(amount)
                except ValueError:
                    continue

    if total == int(total):
        print(int(total))
    else:
        print(total)

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('payload')
    args = parser.parse_args()
    config = json.loads(args.payload)
    main(config['customers'], config['orders'])

import argparse
import json

KEYWORDS = {
    "refund": ["refund", "money back", "reimburse"],
    "exchange": ["exchange", "swap", "replacement", "different size"],
    "cancellation": ["cancel", "terminate", "stop my order"],
}

def classify(text):
    lowered = text.lower()
    scores = {
        intent: sum(lowered.count(keyword) for keyword in keywords)
        for intent, keywords in KEYWORDS.items()
    }
    return max(scores, key=scores.get)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    with open(payload["path"], "r", encoding="utf-8") as handle:
        print(classify(handle.read()))

if __name__ == "__main__":
    main()
